function rotr(x, n) {
  return ((x >>> n) | (x << (32 - n))) >>> 0;
}

// Compute the SHA-256 digest of `bytes` (array of ints 0-255).
// Returns an array of 32 byte values.
export function sha256(bytes) {
  // --- Padding ---
  const msg = bytes.slice();
  const bitLen = bytes.length * 8;
  msg.push(0x80);
  while (msg.length % 64 !== 56) msg.push(0);
  // Append 64-bit big-endian bit length. Lengths here always fit in 53 bits.
  for (let i = 7; i >= 0; i--) {
    msg.push(Math.floor(bitLen / 2 ** (8 * i)) & 0xff);
