// Helpers to reproduce Python's print() output formatting.

// Render a byte array exactly like Python's repr() of a `bytes` object,
// which is what print() emits for bytes values.
export function bytesRepr(bytes) {
  const hasSingle = bytes.includes(0x27); // '
  const hasDouble = bytes.includes(0x22); // "
  // CPython prefers single quotes, switching to double quotes only when the
  // data contains a single quote but no double quote.
  const quote = hasSingle && !hasDouble ? '"' : "'";
  const quoteCode = quote.charCodeAt(0);

  let out = 'b' + quote;
  for (const b of bytes) {
    if (b === 0x5c) {
      out += '\\\\';
    } else if (b === quoteCode) {
      out += '\\' + quote;
    } else if (b === 0x09) {
      out += '\\t';
    } else if (b === 0x0a) {
      out += '\\n';
    } else if (b === 0x0d) {
      out += '\\r';
    } else if (b >= 0x20 && b < 0x7f) {
      out += String.fromCharCode(b);
    } else {
      out += '\\x' + b.toString(16).padStart(2, '0');
    }
  }
  return out + quote;
}

