// Minimal command-line parser matching Python argparse behaviour for the
// option shapes used by the source script: required `--name value` options
// with `str` and `int` types. No external dependencies.

function fail(message, prog, specs) {
  const parts = specs.map((s) => `--${s.name} ${s.name.toUpperCase()}`);
  process.stderr.write(`usage: ${prog} [-h] ${parts.join(' ')}\n`);
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

// specs: [{ name, type: 'str' | 'int', required }]
export function parseArgs(argv, specs, prog = 'test20.mjs') {
  const byName = new Map(specs.map((s) => [s.name, s]));
  const values = {};
  const missing = [];

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    let name = null;
    let inlineValue = null;

    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(2, eq);
        inlineValue = token.slice(eq + 1);
      } else {
        name = token.slice(2);
      }
    }

    const spec = name !== null ? byName.get(name) : undefined;
    if (!spec) {
      fail(`unrecognized arguments: ${token}`, prog, specs);
    }

    let raw;
    if (inlineValue !== null) {
      raw = inlineValue;
    } else {
      i += 1;
      if (i >= argv.length) {
        fail(`argument --${name}: expected one argument`, prog, specs);
      }
      raw = argv[i];
    }

    if (spec.type === 'int') {
      const trimmed = raw.trim().replace(/_/g, '');
      if (!/^[+-]?\d+$/.test(trimmed)) {
        fail(
          `argument --${name}: invalid int value: '${raw}'`,
          prog,
          specs
        );
      }
      values[name] = BigInt(trimmed);
    } else {
      values[name] = raw;
    }
  }

  for (const spec of specs) {
    if (spec.required && !(spec.name in values)) missing.push(`--${spec.name}`);
  }
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.join(', ')}`, prog, specs);
  }

  return values;
}

